"""AMD GPU probe and ROCm PyTorch install for the engine runtime.

Official ``pip install`` into system Python is invisible here: Qwen3 / SenseVoice
import torch from ``transub-engine/runtime/python.exe`` only. NVIDIA CUDA wheels
do not run on Radeon. This module detects the card and installs AMD's ROCm
torch into that interpreter.
"""

from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
from functools import lru_cache
from pathlib import Path
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]

# Official Windows / multi-arch indexes (AMD ROCm PyTorch, 2026).
# gfx1201 = RX 9070 / 9070 XT / AI PRO R9700.
ROCM_INDEX_URLS: tuple[str, ...] = (
    "https://stable.repo.amd.com/rocm/whl-next/",
    "https://repo.amd.com/rocm/whl-multi-arch/",
)
# Windows: torch 2.12.0+rocm10.0.0 + torchaudio 2.11.0.2+rocm10.0.0 loads, then
# libtorchaudio.pyd fails with entry-point torch_new_stable_ivalue (Qwen/Whisper
# crash-loop). AMD's documented pair is rocm10.1.0 + torchaudio 2.11.0 (not .2).
ROCM_TORCH_PIN = "2.12.0+rocm10.1.0"
ROCM_VISION_PIN = "0.27.0+rocm10.1.0"
ROCM_AUDIO_PIN = "2.11.0+rocm10.1.0"
_PYPI_EXTRA = "https://pypi.org/simple"

_GFX_RULES: tuple[tuple[re.Pattern[str], str], ...] = (
    (re.compile(r"9070|R9700|R9600", re.I), "gfx1201"),
    (re.compile(r"9060|9050", re.I), "gfx1200"),
    (re.compile(r"7900|W7900", re.I), "gfx1100"),
    (re.compile(r"7800|7700|W7800|W7700", re.I), "gfx1101"),
    (re.compile(r"7600", re.I), "gfx1102"),
    (re.compile(r"AI\s*Max\+?\s*395|Strix\s*Halo", re.I), "gfx1151"),
)
_HIP_DLL_NAMES = ("c10_hip.dll", "torch_hip.dll", "amdhip64.dll")


def gfx_for_gpu_name(name: str | None) -> str:
    """Map a marketing name to an AMD ``device-gfx*`` extra. Unknown → ``all``."""
    text = str(name or "")
    for pattern, gfx in _GFX_RULES:
        if pattern.search(text):
            return gfx
    return "all"


def amd_device_package_names(gfx: str | None = None) -> list[str]:
    """Separate AMD wheels that actually contain gfx* HIP kernels (~50MB).

    Bare ``torch==X+rocm10`` is only the 100MB+ host package. Without
    ``amd-torch-device-gfx1100`` (etc.) Qwen3 dies with
    ``hipErrorInvalidImage`` / ``device kernel image is invalid``.
    """
    target = str(gfx or "all").strip() or "all"
    if target == "all":
        return []
    names = [f"amd-torch-device-{target}", f"amd-torchvision-device-{target}"]
    return names


def _dist_version(name: str) -> str:
    try:
        from importlib.metadata import version

        return str(version(name) or "").strip()
    except Exception:
        return ""


def _version_core(ver: str | None) -> str:
    return str(ver or "").split("+", 1)[0].strip().lower()


def amd_device_kernels_present(gfx: str | None = None) -> bool:
    """True when the gfx-specific kernel extra matches this torch, or gfx is unknown."""
    target = str(gfx or "all").strip() or "all"
    if target == "all":
        return True
    extra_ver = _dist_version(f"amd-torch-device-{target}")
    if not extra_ver:
        return False
    torch_ver = _torch_version_text()
    if not is_acceptable_rocm_torch_version(torch_ver):
        return False
    extra_core = _version_core(extra_ver)
    torch_core = _version_core(torch_ver)
    if extra_core and torch_core and extra_core != torch_core:
        return False
    return True


def rocm_pip_specs(gfx: str | None = None, *, pinned: bool = True) -> list[str]:
    """PEP 508 requirements for the ROCm torch stack (host + gfx kernels)."""
    target = str(gfx or "all").strip() or "all"
    extra = "device-all" if target == "all" else f"device-{target}"
    if pinned:
        specs = [
            f"torch[{extra}]=={ROCM_TORCH_PIN}",
            f"torchvision[{extra}]=={ROCM_VISION_PIN}",
            # torchaudio has no device-* extras on AMD's index (unlike torch/vision).
            f"torchaudio=={ROCM_AUDIO_PIN}",
        ]
        if target != "all":
            specs.extend(
                [
                    f"amd-torch-device-{target}=={ROCM_TORCH_PIN}",
                    f"amd-torchvision-device-{target}=={ROCM_VISION_PIN}",
                ]
            )
        return specs
    specs = [
        f"torch[{extra}]",
        f"torchvision[{extra}]",
        f"torchaudio=={ROCM_AUDIO_PIN}",
    ]
    specs.extend(amd_device_package_names(target))
    return specs


def rocm_pip_command(gfx: str | None = None, *, python_exe: str = "") -> str:
    """One-line install command for the manual-repair hint."""
    exe = str(python_exe or sys.executable).strip() or "python"
    gfx_id = str(gfx or "all").strip() or "all"
    specs = " ".join(f'"{item}"' for item in rocm_pip_specs(gfx_id, pinned=True))
    index = ROCM_INDEX_URLS[0]
    extras = amd_device_package_names(gfx_id)
    extra_line = ""
    if extras:
        extra_pkgs = " ".join(extras)
        extra_line = (
            f'\n"{exe}" -m pip install --upgrade --index-url {index} '
            f"--extra-index-url {_PYPI_EXTRA} {extra_pkgs}"
        )
    return (
        f'"{exe}" -m pip install --upgrade --force-reinstall '
        f"--index-url {index} --extra-index-url {_PYPI_EXTRA} {specs}"
        f"{extra_line}"
        "\n# 必须带 torch[device-gfx*] / amd-torch-device-gfx*；不要只装 torch==x+rocm（缺内核会 hipErrorInvalidImage）。"
        "\n# 成功后再执行: python -m pip install \"numpy>=2.0,<2.5\""
        "\n# 请用 cmd.exe；PowerShell 可能拆坏版本号里的 +。成功标志：torch.__version__ 含 +rocm10（不是 2.14.x 无后缀）。"
    )


def _nvidia_smi_lists_gpu() -> bool:
    """True when nvidia-smi reports at least one GPU (not merely that the CLI exists)."""
    if not shutil.which("nvidia-smi"):
        return False
    try:
        out = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=5,
            stderr=subprocess.DEVNULL,
        )
        return any(str(line or "").strip() for line in str(out or "").splitlines())
    except Exception:
        return False


def _nvidia_present() -> bool:
    """True when a real NVIDIA GPU is present.

    Do **not** treat leftover ``nvcuda.dll`` / empty ``nvidia-smi`` as NVIDIA —
    that hid Radeon RX 7900-class cards, blocked ROCm install, and let Qwen
    force-heal pull CUDA ``+cu126`` wheels onto AMD machines.
    """
    return _nvidia_smi_lists_gpu()


def _video_controllers() -> list[dict[str, Any]]:
    """Name + AdapterRAM (bytes) for Windows; name-only elsewhere."""
    if os.name == "nt":
        try:
            out = subprocess.check_output(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-Command",
                    (
                        "Get-CimInstance Win32_VideoController "
                        "| Select-Object Name,AdapterRAM "
                        "| ConvertTo-Json -Compress"
                    ),
                ],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            return []
        text = str(out or "").strip()
        if not text:
            return []
        try:
            data = __import__("json").loads(text)
        except Exception:
            return []
        rows = data if isinstance(data, list) else [data]
        result: list[dict[str, Any]] = []
        for row in rows:
            if not isinstance(row, dict):
                continue
            name = str(row.get("Name") or "").strip()
            if not name:
                continue
            try:
                ram = int(row.get("AdapterRAM") or 0)
            except Exception:
                ram = 0
            # Win32 AdapterRAM is often signed; treat as unsigned 32-bit when negative.
            if ram < 0:
                ram = ram & 0xFFFFFFFF
            result.append({"name": name, "adapterRam": ram})
        return result
    if shutil.which("lspci"):
        try:
            out = subprocess.check_output(
                ["lspci", "-nn"],
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=8,
                stderr=subprocess.DEVNULL,
            )
        except Exception:
            return []
        rows: list[dict[str, Any]] = []
        for line in str(out or "").splitlines():
            if re.search(r"VGA|3D|Display", line, re.I) and re.search(r"AMD|ATI|Radeon", line, re.I):
                rows.append({
                    "name": re.sub(r"^[^:]+:\s*", "", line).strip(),
                    "adapterRam": 0,
                })
        return rows
    return []


def _clean_gpu_name(raw: str) -> str:
    text = re.sub(r"\s*\(.*?Radeon.*?\)\s*", " ", str(raw or ""), flags=re.I)
    return re.sub(r"\s+", " ", text).strip()


@lru_cache(maxsize=1)
def probe_amd_gpu() -> dict[str, Any]:
    """First discrete/iGPU AMD adapter, or empty when NVIDIA owns the machine.

    Filesystem / WMI only — do not import torch.
    """
    if _nvidia_present():
        return {}
    for row in _video_controllers():
        raw = str(row.get("name") or "")
        if not re.search(r"radeon|amd", raw, re.I):
            continue
        if re.search(r"microsoft\s*basic", raw, re.I):
            continue
        name = _clean_gpu_name(raw) or raw.strip()
        ram = int(row.get("adapterRam") or 0)
        vram_mb = int(ram // (1024 * 1024)) if ram > 0 else 0
        # AdapterRAM often caps at ~4GB; leave 0 when absurdly small for discrete cards.
        if vram_mb > 0 and vram_mb < 512:
            vram_mb = 0
        return {"name": name, "gfx": gfx_for_gpu_name(name), "vramMb": vram_mb}
    return {}


def amd_gpu_present() -> bool:
    return bool(probe_amd_gpu().get("name"))


def _torch_version_text() -> str:
    """Version string from disk first so a just-finished pip install is visible."""
    from .device import read_torch_version, torch_package_dir

    version_py = torch_package_dir() / "version.py"
    if version_py.is_file():
        try:
            text = version_py.read_text(encoding="utf-8", errors="replace")
        except Exception:
            text = ""
        for line in text.splitlines():
            if line.startswith("__version__"):
                parts = line.split("=", 1)
                if len(parts) == 2:
                    return parts[1].strip().strip("'\"").strip()
    return str(read_torch_version() or "")


def _rocm_major_from_version(ver: str) -> int | None:
    """Parse ``+rocm10.0.0`` / ``.rocm7.14.1`` → major int, else None."""
    m = re.search(r"[+.]rocm(\d+)", str(ver or "").lower())
    if not m:
        return None
    try:
        return int(m.group(1))
    except Exception:
        return None


def rocm_windows_audio_abi_broken() -> bool:
    """True for the Windows pair that crashes in libtorchaudio.pyd.

    Metadata still says +rocm, so a disk-only torch-present check skips repair
    and Qwen/Whisper keep dying. Do not import torchaudio here: the bad pyd
    raises a native entry-point dialog instead of a Python exception.
    """
    audio = _dist_version("torchaudio").lower()
    torch_ver = _torch_version_text().lower()
    if "2.11.0.2" in audio and "rocm10.0" in audio:
        return True
    if "+rocm10.0.0" in torch_ver or torch_ver.endswith("+rocm10.0"):
        return True
    return False


def is_acceptable_rocm_torch_version(ver: str | None) -> bool:
    """Reject plain PyPI torch and ancient multi-arch ``+rocm7`` builds."""
    major = _rocm_major_from_version(ver or "")
    return major is not None and major >= 10


def torch_rocm_libs_present() -> bool:
    """True when this interpreter has a ROCm torch wheel on disk (no LoadLibrary)."""
    from .device import torch_package_dir

    lib = torch_package_dir() / "lib"
    ver = _torch_version_text().lower()
    # Prefer a real +rocmN version string so leftover HIP DLLs cannot mask a PyPI torch.
    if is_acceptable_rocm_torch_version(ver):
        return lib.is_dir()
    # Reject ancient multi-arch +rocm7 even if HIP DLLs remain on disk.
    major = _rocm_major_from_version(ver)
    if major is not None and major < 10:
        return False
    if not lib.is_dir():
        return False
    # Legacy: HIP DLLs only count when the version string also claims ROCm.
    if "+rocm" not in ver and ".rocm" not in ver:
        return False
    for name in _HIP_DLL_NAMES:
        if (lib / name).is_file():
            return True
    try:
        return any(lib.glob("*hip*.dll")) or any(lib.glob("*hip*.so*"))
    except Exception:
        return False


def torch_is_rocm() -> bool:
    """True when this engine Python's torch is a ROCm/HIP build."""
    if torch_rocm_libs_present():
        return True
    try:
        import torch

        return bool(getattr(torch.version, "hip", None))
    except Exception:
        return False


def rocm_runtime_dirs() -> list[str]:
    """Directories that may hold HIP / torch native DLLs. Filesystem only."""
    dirs: list[str] = []
    seen: set[str] = set()

    def add(path: Path) -> None:
        if not path.is_dir():
            return
        try:
            key = str(path.resolve()).lower()
        except Exception:
            key = str(path).lower()
        if key in seen:
            return
        seen.add(key)
        dirs.append(str(path))

    from .device import torch_package_dir

    lib = torch_package_dir() / "lib"
    add(lib)
    roots = [
        Path(sys.prefix) / "Lib" / "site-packages",
        Path(sys.prefix) / "lib" / f"python{sys.version_info.major}.{sys.version_info.minor}" / "site-packages",
    ]
    markers = _HIP_DLL_NAMES
    for root in roots:
        if not root.is_dir():
            continue
        try:
            children = list(root.iterdir())
        except Exception:
            continue
        for child in children:
            if not child.is_dir():
                continue
            for sub in (child, child / "bin", child / "lib", child / "lib" / "x64"):
                try:
                    hit = any((sub / name).is_file() for name in markers)
                except Exception:
                    hit = False
                if hit:
                    add(sub)
    return dirs


def _emit(on_progress: ProgressCb | None, payload: dict[str, Any]) -> None:
    if not on_progress:
        return
    try:
        on_progress(payload)
    except Exception:
        pass


def probe_torchaudio_import() -> tuple[bool, str]:
    """True when torchaudio loads against the engine's ROCm/CUDA torch build.

    WinError 127 on libtorchaudio.pyd is the classic hybrid (CPU/CUDA wheel over
    ROCm torch, or missing HIP deps). Metadata can still report +rocm*.
    """
    try:
        import torch  # noqa: F401

        import torchaudio  # noqa: F401

        return True, ""
    except Exception as err:
        return False, str(err).strip() or type(err).__name__


def probe_torchvision_import() -> tuple[bool, str]:
    """True when torchvision imports cleanly against the engine's torch build."""
    try:
        import torch  # noqa: F401

        import torchvision  # noqa: F401

        return True, ""
    except Exception as err:
        return False, str(err).strip() or type(err).__name__


def reconcile_broken_torchvision(
    *,
    gfx: str = "",
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Reinstall matching ROCm torchvision when it breaks transformers (never uninstall)."""
    ok, err = probe_torchvision_import()
    if ok:
        return {"ok": True, "action": "ok", "message": ""}

    gfx_id = str(gfx or probe_amd_gpu().get("gfx") or "all").strip() or "all"
    extra = "device-all" if gfx_id == "all" else f"device-{gfx_id}"
    torch_core = _version_core(_torch_version_text())
    pin_core = _version_core(ROCM_TORCH_PIN)
    vision_attempts: list[str] = [
        f"torchvision[{extra}]",
    ]
    if gfx_id != "all":
        vision_attempts.append(f"amd-torchvision-device-{gfx_id}")
    # Only reuse the catalog pin when this interpreter is still on that torch.
    if torch_core and pin_core and torch_core == pin_core:
        vision_attempts.insert(0, f"torchvision[{extra}]=={ROCM_VISION_PIN}")
    _emit(
        on_progress,
        {
            "type": "progress",
            "stage": "torch_rocm",
            "percent": 85,
            "detail": "正在修复 ROCm torchvision 与 PyTorch 的匹配…",
        },
    )
    last = err
    for index in ROCM_INDEX_URLS:
        for spec in vision_attempts:
            code, tail = _pip_install(index, [spec], timeout_sec=20 * 60)
            if code == 0 and probe_torchvision_import()[0]:
                return {
                    "ok": True,
                    "action": "reinstalled",
                    "message": "已重装匹配的 ROCm torchvision",
                }
            if tail:
                last = tail

    return {
        "ok": False,
        "action": "failed",
        "message": (
            "torchvision 与 ROCm PyTorch 不匹配，且重装失败。"
            "不要卸载 torchvision（transformers / Qwen3 Processor 需要 torchvision.io）。"
            "请用带 device-gfx 附加包的命令重装整栈。"
            f"原错误：{(err or last or '')[:200]}"
        ),
    }


def _pin_numpy_for_numba() -> None:
    """ROCm extra-index PyPI often floats numpy to 2.5+ and breaks numba."""
    try:
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "numpy>=2.0,<2.5",
            ],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=600,
            capture_output=True,
            check=False,
        )
    except Exception:
        pass


def _pip_install(
    index_url: str,
    specs: list[str],
    *,
    timeout_sec: float,
    force_reinstall: bool = True,
) -> tuple[int, str]:
    cmd = [
        sys.executable,
        "-u",
        "-m",
        "pip",
        "install",
        "--upgrade",
        *(["--force-reinstall"] if force_reinstall else []),
        "--index-url",
        index_url,
        "--extra-index-url",
        _PYPI_EXTRA,
        *specs,
    ]
    try:
        proc = subprocess.run(
            cmd,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout_sec,
            capture_output=True,
        )
    except subprocess.TimeoutExpired as err:
        tail = str(err.stderr or err.stdout or "")[-800:]
        return 1, f"pip 超时：{tail}"
    except Exception as err:
        return 1, str(err)
    tail = ((proc.stderr or "") + "\n" + (proc.stdout or "")).strip()
    return int(proc.returncode or 0), tail[-1200:]


def _uninstall_broken_rocm_stack() -> None:
    """Drop the crashing rocm10.0 torch/torchaudio wheels before the 10.1 pair."""
    names = [
        "torch",
        "torchaudio",
        "torchvision",
        "amd-torch-device-gfx1201",
        "amd-torch-device-gfx1200",
        "amd-torch-device-gfx1100",
        "amd-torch-device-gfx1101",
        "amd-torch-device-gfx1102",
        "amd-torchvision-device-gfx1201",
        "amd-torchvision-device-gfx1200",
        "amd-torchvision-device-gfx1100",
        "amd-torchvision-device-gfx1101",
        "amd-torchvision-device-gfx1102",
    ]
    try:
        subprocess.run(
            [sys.executable, "-m", "pip", "uninstall", "-y", *names],
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=15 * 60,
            capture_output=True,
        )
    except Exception:
        pass
    root = Path(sys.prefix) / "Lib" / "site-packages"
    for folder in ("torch", "torchaudio", "torchvision"):
        target = root / folder
        if target.is_dir():
            shutil.rmtree(target, ignore_errors=True)


def install_torch_rocm(
    *,
    force: bool = True,
    on_progress: ProgressCb | None = None,
    gfx: str = "",
) -> dict[str, Any]:
    """Install AMD ROCm PyTorch into this engine interpreter."""
    if _nvidia_present():
        return {
            "ok": False,
            "skipped": True,
            "code": "NVIDIA_PRESENT",
            "message": "本机有 NVIDIA GPU，不安装 ROCm PyTorch",
        }
    probe = probe_amd_gpu()
    gfx_id = str(gfx or probe.get("gfx") or "all").strip() or "all"
    name = str(probe.get("name") or "AMD GPU")
    _ = force
    torch_ok = torch_rocm_libs_present() and is_acceptable_rocm_torch_version(
        _torch_version_text()
    )
    kernels_ok = amd_device_kernels_present(gfx_id)
    abi_broken = rocm_windows_audio_abi_broken()
    # A healthy 10.1 + gfx kernel install stays skipped. The crashing
    # rocm10.0 / torchaudio 2.11.0.2 pair must be replaced even if HIP DLLs exist.
    if torch_ok and kernels_ok and not abi_broken:
        return {
            "ok": True,
            "skipped": True,
            "code": "",
            "installed": ["torch"],
            "gfx": gfx_id,
            "message": f"引擎运行时已有 ROCm PyTorch（{name}）",
        }

    extras = amd_device_package_names(gfx_id)
    if torch_ok and extras and not kernels_ok and not abi_broken:
        _emit(
            on_progress,
            {
                "type": "progress",
                "stage": "torch_rocm",
                "percent": 25,
                "detail": f"正在补齐 {gfx_id} HIP 内核包（amd-torch-device）…",
            },
        )
        last_extra = ""
        for index in ROCM_INDEX_URLS:
            code, tail = _pip_install(
                index, extras, timeout_sec=50 * 60, force_reinstall=False
            )
            if code != 0:
                last_extra = tail or f"pip exit {code}"
                continue
            ver = _torch_version_text()
            if is_acceptable_rocm_torch_version(ver) and amd_device_kernels_present(gfx_id):
                _pin_numpy_for_numba()
                tv = reconcile_broken_torchvision(gfx=gfx_id, on_progress=on_progress)
                msg = f"已补齐 ROCm HIP 内核包（{ver or gfx_id}，{name}）"
                if tv.get("action") not in ("ok", None):
                    tv_msg = str(tv.get("message") or "").strip()
                    if tv_msg:
                        msg += f"；{tv_msg}"
                return {
                    "ok": True,
                    "code": "",
                    "installed": extras,
                    "gfx": gfx_id,
                    "version": ver,
                    "message": msg,
                    "pipCommand": rocm_pip_command(gfx_id),
                    "torchvision": tv,
                }
            last_extra = tail or "内核包安装后仍不匹配"
        last_err = last_extra
    else:
        last_err = ""

    if abi_broken:
        _uninstall_broken_rocm_stack()
    attempts: list[tuple[str, list[str]]] = []
    for index in ROCM_INDEX_URLS:
        # Pinned 2.12+rocm10.1 first (known-good Windows pair). Unpinned is only
        # a fallback when that exact wheel is missing from the index.
        attempts.append((index, rocm_pip_specs(gfx_id, pinned=True)))
        if not abi_broken:
            attempts.append((index, rocm_pip_specs(gfx_id, pinned=False)))
    for index, specs in attempts:
        _emit(
            on_progress,
            {
                "type": "progress",
                "stage": "torch_rocm",
                "percent": 20,
                "detail": f"正在安装 ROCm PyTorch（{gfx_id}，{name}）…",
                "mirror": index,
            },
        )
        code, tail = _pip_install(index, specs, timeout_sec=50 * 60)
        if code != 0:
            last_err = tail or f"pip exit {code}"
            continue
        from .device import read_torch_version

        ver = _torch_version_text() or read_torch_version()
        if not is_acceptable_rocm_torch_version(ver):
            last_err = (
                tail
                or f"pip 装到了非 ROCm10+ 的 torch（{ver or 'unknown'}），已拒绝。"
                "请确认能访问 stable.repo.amd.com，勿混用 PyPI / 旧 multi-arch rocm7 轮子。"
            )
            continue
        if torch_rocm_libs_present():
            if gfx_id != "all" and not amd_device_kernels_present(gfx_id):
                last_err = (
                    tail
                    or f"已装 ROCm torch（{ver}）但缺少 {gfx_id} 内核包 amd-torch-device-{gfx_id}。"
                    "裸装 torch==x+rocm 没有 HIP kernel image。"
                )
                continue
            _pin_numpy_for_numba()
            tv = reconcile_broken_torchvision(gfx=gfx_id, on_progress=on_progress)
            audio_ok, audio_err = probe_torchaudio_import()
            if not audio_ok:
                # Force reinstall torchaudio pin only (torch host already ROCm).
                for index in ROCM_INDEX_URLS:
                    code, tail = _pip_install(
                        index,
                        [f"torchaudio=={ROCM_AUDIO_PIN}"],
                        timeout_sec=20 * 60,
                    )
                    if code == 0 and probe_torchaudio_import()[0]:
                        audio_ok, audio_err = True, ""
                        break
                    if tail:
                        audio_err = tail
                if not audio_ok:
                    return {
                        "ok": False,
                        "code": "TORCHAUDIO_ROCM_LOAD_FAILED",
                        "gfx": gfx_id,
                        "version": ver,
                        "message": (
                            "ROCm torch 已装但 torchaudio 无法加载（常见 WinError 127）。"
                            f"请完全退出后重装 ROCm 栈：\n{rocm_pip_command(gfx_id)}\n"
                            f"原因：{(audio_err or '')[:240]}"
                        ),
                        "pipCommand": rocm_pip_command(gfx_id),
                    }
            msg = f"已把 ROCm PyTorch 装进引擎运行时（{ver or gfx_id}，{name}）"
            if tv.get("action") not in ("ok", None):
                tv_msg = str(tv.get("message") or "").strip()
                if tv_msg:
                    msg += f"；{tv_msg}"
            return {
                "ok": True,
                "code": "",
                "installed": ["torch", "torchvision", "torchaudio"],
                "gfx": gfx_id,
                "version": ver,
                "message": msg,
                "pipCommand": rocm_pip_command(gfx_id),
                "torchvision": tv,
            }
        last_err = tail or f"pip 成功但未发现可用的 ROCm torch（{ver or 'unknown'}）"

    return {
        "ok": False,
        "code": "TORCH_ROCM_INSTALL_FAILED",
        "gfx": gfx_id,
        "message": (
            f"安装 ROCm PyTorch 失败（{name} / {gfx_id}）。"
            "请确认已安装 AMD 显卡驱动，再用下面的命令装进引擎 Python：\n"
            + rocm_pip_command(gfx_id)
            + (f"\n{last_err}" if last_err else "")
        ),
        "pipCommand": rocm_pip_command(gfx_id),
        "suggestManual": True,
    }
